// Button Component
function Button({ children, onClick, variant = 'default', size = 'default', className = '', disabled = false, ...props }) {
  const baseStyle = "px-4 py-2 rounded-md font-medium transition-colors duration-200";
  let variantStyle = "bg-blue-600 text-white hover:bg-blue-700"; // Default
  if (variant === 'outline') {
    variantStyle = "border border-gray-300 bg-white text-gray-700 hover:bg-gray-100";
  } else if (variant === 'secondary') {
    variantStyle = "bg-gray-200 text-gray-800 hover:bg-gray-300";
  } else if (variant === 'destructive') {
    variantStyle = "bg-red-600 text-white hover:bg-red-700";
  } else if (variant === 'ghost') {
    variantStyle = "bg-transparent text-gray-700 hover:bg-gray-100";
  }

  let sizeStyle = "";
  if (size === 'sm') {
    sizeStyle = "px-3 py-1.5 text-sm";
  }

  return (
    <button
      onClick={onClick}
      className={`${baseStyle} ${variantStyle} ${sizeStyle} ${className} ${disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
      disabled={disabled}
      {...props}
    >
      {children}
    </button>
  );
}

