// Popover Component (simplified - will just render content directly if open)
function Popover({ children, open, onOpenChange }) {
  const [trigger, content] = React.Children.toArray(children);
  const [internalOpen, setInternalOpen] = useState(false); // Internal state for uncontrolled Popover

  const currentOpen = open !== undefined ? open : internalOpen;

  const handleOpenChange = (val) => {
    if (onOpenChange) {
      onOpenChange(val);
    }
    setInternalOpen(val);
  };

  // Clone the trigger element to inject the onClick handler
  const triggerElement = React.isValidElement(trigger)
    ? React.cloneElement(trigger, {
        onClick: (e) => {
          if (trigger.props.onClick) {
            trigger.props.onClick(e);
          }
          handleOpenChange(!currentOpen);
        },
      })
    : (
        <button onClick={() => handleOpenChange(!currentOpen)}>
          {trigger}
        </button>
      );

  return (
    <div className="relative">
      {triggerElement}
      {currentOpen && (
        <div className="absolute z-50 bg-white border border-gray-200 rounded-md shadow-lg mt-2">
          {content}
        </div>
      )}
    </div>
  );
}

function PopoverTrigger({ children, asChild, ...props }) {
  return asChild ? children : <button {...props}>{children}</button>;
}

function PopoverContent({ children, className = '' }) {
  return (
    <div className={`p-2 ${className}`}>{children}</div>
  );
}

// Calendar Component (simplified - basic date selection)
function Calendar({ selected, onSelect, mode = 'single', initialFocus }) {
  const [currentMonth, setCurrentMonth] = useState(selected || new Date());

  const daysInMonth = (date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    return new Date(year, month + 1, 0).getDate();
  };

  const firstDayOfMonth = (date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    return new Date(year, month, 1).getDay(); // 0 for Sunday, 1 for Monday, etc.
  };

  const handlePrevMonth = () => {
    setCurrentMonth(prev => new Date(prev.getFullYear(), prev.getMonth() - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentMonth(prev => new Date(prev.getFullYear(), prev.getMonth() + 1, 1));
  };

  const renderDays = () => {
    const totalDays = daysInMonth(currentMonth);
    const startDay = firstDayOfMonth(currentMonth);
    const days = [];

    // Fill leading empty days
    for (let i = 0; i < startDay; i++) {
      days.push(<div key={`empty-start-${i}`} className="w-10 h-10"></div>);
    }

    // Fill actual days
    for (let i = 1; i <= totalDays; i++) {
      const date = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), i);
      const isSelected = selected && format(selected, 'yyyy-MM-dd') === format(date, 'yyyy-MM-dd');
      const isToday = format(new Date(), 'yyyy-MM-dd') === format(date, 'yyyy-MM-dd');

      days.push(
        <button
          key={i}
          className={`w-10 h-10 flex items-center justify-center rounded-full text-sm
            ${isSelected ? 'bg-blue-600 text-white' : ''}
            ${isToday && !isSelected ? 'border border-blue-500 text-blue-700' : ''}
            ${!isSelected && !isToday ? 'hover:bg-gray-100' : ''}
          `}
          onClick={() => onSelect(date)}
        >
          {i}
        </button>
      );
    }

    return days;
  };

  return (
    <div className="p-4 bg-white rounded-md shadow-md">
      <div className="flex justify-between items-center mb-4">
        <Button size="sm" variant="ghost" onClick={handlePrevMonth}>&lt;</Button>
        <span className="font-semibold">{format(currentMonth, 'MMMM yyyy')}</span>
        <Button size="sm" variant="ghost" onClick={handleNextMonth}>&gt;</Button>
      </div>
      <div className="grid grid-cols-7 gap-1 text-center text-xs font-medium text-gray-500 mb-2">
        <div>Su</div>
        <div>Mo</div>
        <div>Tu</div>
        <div>We</div>
        <div>Th</div>
        <div>Fr</div>
        <div>Sa</div>
      </div>
      <div className="grid grid-cols-7 gap-1">
        {renderDays()}
      </div>
    </div>
  );
}


