  const searchUsdaFood = async (queryTerm, isBarcodeSearch = false) => {
    if (!queryTerm.trim()) {
      setInfoModalTitle('Search Error');
      setInfoModalMessage('Please enter a food name or scan a barcode to search.');
      setShowInfoModal(true);
      return;
    }
    setIsSearchingUsda(true);
    setUsdaSearchResults([]);
    try {
      let apiUrl;
      if (isBarcodeSearch) {
        // Search by gtinUpc for barcode scans
        apiUrl = `https://api.nal.usda.gov/fdc/v1/foods/search?api_key=${USDA_API_KEY}&query=${encodeURIComponent(queryTerm)}&dataType=Branded&pageSize=1`; // Limit to 1 result for barcode
      } else {
        // General text search
        apiUrl = `https://api.nal.usda.gov/fdc/v1/foods/search?api_key=${USDA_API_KEY}&query=${encodeURIComponent(queryTerm)}&dataType=Branded,Foundation,SR Legacy`;
      }

      const response = await fetch(apiUrl);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      console.log('USDA Search Results:', data);

      const parsedResults = (data.foods || []).map(food => {
        const nutrients = food.foodNutrients || [];
        const getNutrient = (name) => nutrients.find(n => n.nutrientName.toLowerCase().includes(name.toLowerCase()))?.value || 0;

        return {
          fdcId: food.fdcId,
          description: food.description,
          brandOwner: food.brandOwner,
          dataType: food.dataType,
          totalCarbs: getNutrient('Carbohydrate, by difference'),
          fiber: getNutrient('Fiber, total dietary'),
          protein: getNutrient('Protein'),
          fat: getNutrient('Total lipid (fat)'),
          calories: getNutrient('Energy'), // Calories are typically 'Energy' in kcal
          servingSize: food.servingSize || 100, // Default to 100g if not specified
          servingSizeUnit: food.servingSizeUnit || 'g',
        };
      });
      setUsdaSearchResults(parsedResults);

      if (isBarcodeSearch && parsedResults.length > 0) {
        handleSelectUsdaFood(parsedResults[0]); // Automatically select the first result for barcode
        setInfoModalTitle('Barcode Scanned');
        setInfoModalMessage(`Food found for barcode: ${parsedResults[0].description}. Loaded into meal form.`);
        setShowInfoModal(true);
        setShowBarcodeScannerModal(false); // Close scanner after finding food
      } else if (isBarcodeSearch && parsedResults.length === 0) {
        setInfoModalTitle('Food Not Found');
        setInfoModalMessage('No food found for this barcode. Please try manual entry or USDA text search.');
        setShowInfoModal(true);
      }

    } catch (e) {
      console.error('Error searching USDA:', e);
      setInfoModalTitle('USDA Search Error');
      setInfoModalMessage(`Failed to search USDA FoodData Central: ${e.message}. Please ensure your USDA API key is valid.`);
      setShowInfoModal(true);
    } finally {
      setIsSearchingUsda(false);
    }
  };

