  const totalNetCarbs = meals.reduce((sum, meal) => sum + (meal.totalCarbs - meal.fiber), 0);
  const totalTotalCarbs = meals.reduce((sum, meal) => sum + meal.totalCarbs, 0);
  const totalProtein = meals.reduce((sum, meal) => sum + meal.protein, 0);
